export const handleSelectEntity = async (studioPro: StudioProApi, agent: Agent, documentId: string): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectEntity({ allowNone: true });
    if (selectorResult.status === 'ok') {
        console.log(selectorResult);
        const updatedAgent: Agent = { ...agent, entity: selectorResult.selected.module + '.' + selectorResult.selected.name };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
    if (selectorResult.status === 'none') {
        console.log('"None" selected for Entity');
        const updatedAgent: Agent = { ...agent, entity: "" };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
}

export const handleSelectCustomDocument = async (studioPro: StudioProApi, agent: Agent, documentId: string, fieldName: keyof Agent): Promise<Agent | undefined> => {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({ allowNone: true });
    if (selectorResult.status === 'ok') {
        console.log(selectorResult);
        const updatedAgent: Agent = { ...agent, [fieldName]: selectorResult.selected.module + '.' + selectorResult.selected.name };
        console.log(selectorResult.selected.module + '.' + selectorResult.selected.name);
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
    if (selectorResult.status === 'none') {
        console.log('"None" selected for ' + fieldName);
        const updatedAgent: Agent = { ...agent, [fieldName]: undefined };
        await updateAgentDocument(studioPro, updatedAgent, documentId);
        return updatedAgent;
    }
}

export const handleVariableTestValueChange = (studioPro: StudioProApi, agent: Agent, documentId: string) => async (
    index: number,
    value: string
): Promise<Agent> => {
    console.log("variable test value change triggered for index", index);
    const updatedVariables = [...agent.variables];
    updatedVariables[index] = { ...updatedVariables[index], testValue: value };
    const updatedAgent = { ...agent, variables: updatedVariables };
    await updateAgentDocument(studioPro, updatedAgent, documentId);
    return updatedAgent;
};

export const handleValidateAgent = (field: keyof Agent, studioPro: StudioProApi, agent: Agent) => {
    console.log("HandleValidate triggered with field", field);
    switch (field) {
        case "modelQualifiedName":
            if (!agent.modelQualifiedName) {
                console.log("no model name found");
                return "Please select a model";
            }
            const models = (async () => await studioPro.app.model.customBlobDocuments.getDocumentsOfType(modelDocumentTypeId)
                .then((docs: DocumentsOfTypeResult) => docs.find(d => d.name === agent.modelQualifiedName)))();
            break;
        case "entity":
            if (agent.variables.length > 0 && !agent.entity) {
                return "Please select an entity";
            }
            break;
            
        default:
            return true;
    }
    return true;
}


const updateAgentDocument = async (studioPro: StudioProApi, agent: Agent, documentId: string) => {
    console.log("Save logic triggered");
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, agent);
    } catch (error) {
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message
        });
    }
};