import React from 'react';
import { DivFlexColumn, DivFlexRow, StyledBadgeLabel, StyledInput, LabelWrapper } from './elements/formelements';


interface TextInputBadgedProps {
    label?: string;
    ariaLabel: string;
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
    readOnly?: boolean;
    badgeBackgroundColor: string;
    badgeBorderColor: string;
}


const TextInputBadged: React.FC<TextInputBadgedProps> = ({
    label,
    ariaLabel,
    value,
    onChange,
    placeholder,
    readOnly = false,
    badgeBackgroundColor,
    badgeBorderColor,
}) => {
    return (
        <DivFlexRow>
            {label && (
                <DivFlexColumn>
                    <LabelWrapper>
                        <StyledBadgeLabel backgroundcolor={badgeBackgroundColor} bordercolor={badgeBorderColor}>
                            {'\{\{' + label + '\}\}'}
                        </StyledBadgeLabel>
                    </LabelWrapper>
                </DivFlexColumn>
            )}
            <DivFlexColumn fullWidth>
                <StyledInput
                    value={value}
                    placeholder={placeholder}
                    isReadOnly={readOnly}
                    onChange={onChange}
                    aria-label={ariaLabel}
                />
            </DivFlexColumn>
        </DivFlexRow>
    );
};

export default TextInputBadged;
