import React from 'react';
import styled from 'styled-components';
import TextInputBadged from './TextInputBadged';
import { Variable } from '../../types/agent';

const StyledDiv = styled.div`
    display: flex;
    flex-direction: column;
    gap: 8px;
`;

interface VariablesListProps {
    variables: Variable[];
    onVariableChange: (index: number, value: string) => void;
}

const VariablesList: React.FC<VariablesListProps> = ({ variables, onVariableChange }) => {
    return (
        variables.length > 0 ? <StyledDiv>
            {variables.map((variable, index) => (
                <TextInputBadged
                    key={`${variable.key}-${index}`}
                    label={variable.key}
                    ariaLabel={'variable-'+variable.key}
                    value={variable.testValue}
                    onChange={(value: string) => onVariableChange(index, value)}
                    badgeBackgroundColor={variable.backgroundColor}
                    badgeBorderColor={variable.borderColor}
                />
            ))}
        </StyledDiv> : null
    );
};

export default VariablesList;