import { useState, useEffect, useMemo, useCallback } from "react";

import { DocumentLookupResult, IComponent, StudioProApi } from "@mendix/extensions-api";
import { EntityIcon } from "@mendix/ide-icons/EntityIcon";
import { EntityNonPersistableIcon } from "@mendix/ide-icons/EntityNonPersistableIcon";

import { createDocumentEditorComponent } from "../utils/componentLoader";

import { Agent, UsageType } from "../../types/agent";
import { createNewAgent, createHighlightRules, isAgentEntityFound, getEntity, isPersistableEntity } from "../../utils/agentUtils";
import { handleValidateAgent, handleAgentChangeEvent, handleAgentChangeValue, handleSelectEntity, handleSelectCustomDocument, handleVariableTestValueChange } from "./agentHandlers";

import { PageContainer, ContentColumn, PageContent } from "../components/PageContainers";
import AppThemeProvider from "../components/AppThemeProvider";
import { ErrorBanner, InfoBanner } from "../components/Banner";
import FormDivider from "../components/FormDivider"
import TextAreaLabeled from "../components/TextAreaLabeled";
import TextInputLabeled from "../components/TextInputLabeled";
import TextInputWithButton from "../components/TextInputWithButton";
import VariablesList from "../components/VariablesList";
import { mendixCloudGenAIIconBase64 } from "../../icons/modelIcons";


const initialAgent: Agent = createNewAgent()

const usageTypeOptions: { caption: string; value: UsageType }[] = [
    { caption: "Chat", value: "Chat" },
    { caption: "Task", value: "Task" }
]

interface AppProps {
    studioPro: StudioProApi;
    documentId: string;
}

const App: React.FC<AppProps> = ({ studioPro, documentId }) => {
    const messageBoxApi = studioPro.ui.messageBoxes;
    const documentApi = studioPro.app.model.customBlobDocuments;

    const [documentVersion, setDocumentVersion] = useState(0);
    const [isLoaded, setIsLoaded] = useState(false);
    const [isEntityFound, setIsEntityFound] = useState(true);
    const [entityIcon, setEntityIcon] = useState<React.ReactElement | undefined>(undefined);
    const [agent, setAgent] = useState(initialAgent);



    useEffect(() => {
        const handleDocumentsChanged = (event: { documents: Array<{ id: string }> }) => {
            const { documents } = event;
            if (documents.some(doc => doc.id === documentId)) {
                setDocumentVersion(v => v + 1);
            }
        };
        documentApi.addEventListener("documentsChanged", handleDocumentsChanged);
        return () => {
            documentApi.removeEventListener("documentsChanged", handleDocumentsChanged);
        };
    }, []);

    useEffect(() => {
        documentApi
            .getDocumentById<Agent>(documentId)
            .then(async (documentFromModel: DocumentLookupResult<Agent>) => {
                if (documentFromModel && !("error" in documentFromModel)) {
                    const loadedAgent: Agent = documentFromModel.document.contents;
                    setAgent(loadedAgent);
                    setIsEntityFound(await isAgentEntityFound(studioPro, loadedAgent));
                    setIsLoaded(true);
                } else {
                    throw new Error(documentFromModel?.error || "Document not found");
                }
            })
            .catch(err => {
                messageBoxApi.show("error", "Error loading document", "Details: " + err?.message || err);
            });
    }, [documentVersion]);

    useEffect(() => {
        const updateEntityIcon = async () => {
            if (!agent.entity) {
                setEntityIcon(undefined);
                return;
            }

            const entity = await getEntity(studioPro, agent.entity);
            if (!entity) {
                setEntityIcon(undefined);
                return;
            }
            const isPersistable = await isPersistableEntity(entity, studioPro);
            if (isPersistable === undefined) {
                setEntityIcon(undefined);
                return;
            }
            setEntityIcon(isPersistable ? <EntityIcon /> : <EntityNonPersistableIcon />);

        };

        if (isLoaded) {
            updateEntityIcon();
        }

    }, [studioPro, agent.entity, isLoaded]);

    const highlightRules = useMemo(() =>
        createHighlightRules(agent.variables),
        [agent.variables]
    );

    const onChangeEvent = useCallback((fieldName: keyof Agent) =>
        async (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
            const updatedAgent = await handleAgentChangeEvent(studioPro, fieldName, agent, documentId)(e);
            setAgent(updatedAgent);
        }, [studioPro, agent, setAgent, documentId]
    );

    const onChangeValue = useCallback((fieldName: keyof Agent) =>
        async (value: string) => {
            const updatedAgent = await handleAgentChangeValue(studioPro, fieldName, agent, documentId)(value);
            setAgent(updatedAgent);
        }, [studioPro, agent, setAgent, documentId]
    );

    const selectEntity = useCallback(async () => {
        const updatedAgent = await handleSelectEntity(studioPro, agent, documentId);
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    }, [studioPro, agent, setAgent, documentId]
    );

    const selectModel = useCallback(async () => {
        const updatedAgent = await handleSelectCustomDocument(studioPro, agent, documentId, "modelQualifiedName");
        if (updatedAgent) {
            setAgent(updatedAgent);
        }
    }, [studioPro, agent, setAgent, documentId]
    );

    const onVariableChange = useCallback(async (index: number, value: string) => {
        const updatedAgent = await handleVariableTestValueChange(studioPro, agent, documentId)(index, value);
        setAgent(updatedAgent);
    }, [studioPro, agent, setAgent, documentId]
    );

    const validateAgent = (field: keyof Agent) => () => {
        return handleValidateAgent(field, studioPro, agent);
    };

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainer>
                {!isLoaded && <span>Loading document content...</span>}
                {isLoaded && <PageContent>
                    <ContentColumn>
                        <TextInputWithButton
                            ariaLabel="Model"
                            label="Model"
                            value={agent.modelQualifiedName ? agent.modelQualifiedName : ''}
                            icon={agent.modelQualifiedName ? mendixCloudGenAIIconBase64 : undefined}
                            buttonCaption="Select..."
                            onClick={selectModel}
                            buttonCaptionSecondary="Settings"
                            onClickSecondary={() => { }}
                            validate={validateAgent("modelQualifiedName")}
                        />
                        <FormDivider label="System prompt">
                            <TextAreaLabeled
                                ariaLabel="System prompt"
                                value={agent.systemPrompt}
                                onChange={onChangeEvent("systemPrompt")}
                                highlightRules={highlightRules}
                            />
                        </FormDivider>
                        <FormDivider label="User prompt">
                            <TextAreaLabeled
                                ariaLabel="User prompt"
                                value={agent.userPrompt + ''}
                                onChange={onChangeEvent("userPrompt")}
                                highlightRules={highlightRules}
                            />
                        </FormDivider>
                        {/*
                        <FormDivider label="Tools">
                            <Table
                                ariaLabel="Tools table"
                                columns={[
                                    { id: "name", caption: "Tool name", isRowHeader: true },
                                    { id: "description", caption: "Description" }
                                ]}
                                data={agent.tools ? agent.tools.map(tool => [tool.name, tool.description]) : []}
                                emptyMessage="No tools configured."
                                toolbarLeft={
                                    <>
                                        <ToolbarButton
                                            icon={<PageIcon />}
                                            label="New"
                                            onPress={() => console.log("Add tool clicked")}
                                            tooltip="Add new tool"
                                        />
                                        <ToolbarButton
                                            icon={<EditIcon />}
                                            label="Edit"
                                            onPress={() => console.log("Edit tool clicked")}
                                            tooltip="Edit selected tool"
                                        />
                                        <ToolbarButton
                                            icon={<AppSelectorNoVersionIcon />}
                                            label="Delete"
                                            onPress={() => console.log("Delete tool clicked")}
                                            tooltip="Delete selected tool"
                                        />
                                    </>
                                }
                            />
                        </FormDivider>
                        <FormDivider label="Knowledge bases">
                            <Table
                                ariaLabel="Knowledge bases table"
                                columns={[
                                    { id: "name", caption: "Knowledge base name", isRowHeader: true },
                                    { id: "description", caption: "Description" }
                                ]}
                                data={[]}
                                emptyMessage="No knowledge bases configured."
                                toolbarLeft={
                                    <>
                                        <ToolbarButton
                                            icon={<PageIcon />}
                                            label="New"
                                            onPress={() => console.log("Add knowledge base clicked")}
                                            tooltip="Add new knowledge base"
                                        />
                                        <ToolbarButton
                                            icon={<EditIcon />}
                                            label="Edit"
                                            onPress={() => console.log("Edit knowledge base clicked")}
                                            tooltip="Edit selected knowledge base"
                                        />
                                        <ToolbarButton
                                            icon={<AppSelectorNoVersionIcon />}
                                            label="Delete"
                                            onPress={() => console.log("Delete knowledge base clicked")}
                                            tooltip="Delete selected knowledge base"
                                        />
                                    </>
                                }
                            />
                        </FormDivider>
                        */}
                    </ContentColumn>
                    <ContentColumn>
                        <FormDivider label="Variables">
                            <VariablesList
                                variables={agent.variables}
                                onVariableChange={onVariableChange}
                            />
                            {agent.variables.length === 0
                                && <InfoBanner>
                                    {`Create variables: Enclose a word or text in double curly brackets. For example, you can write {{Language}} in the system or user prompt.`}
                                </InfoBanner>}
                        </FormDivider>
                        <FormDivider label="General">
                            <TextInputLabeled
                                label="Agent ID"
                                ariaLabel="Agent ID"
                                value={documentId}
                                onChange={() => { }}
                                readOnly
                            />
                            <TextAreaLabeled
                                label="Documentation"
                                ariaLabel="Documentation"
                                value={agent.description}
                                onChange={onChangeEvent("description")}
                                defaultHeightRows={3}
                            />
                            {/* <RadioButtonGroupLabeled
                                options={usageTypeOptions}
                                label="Agent type"
                                ariaLabel="Agent type"
                                onChange={onChangeValue("usageType")}
                                value={agent.usageType}
                            ></RadioButtonGroupLabeled> */}
                            <TextInputWithButton
                                ariaLabel="Entity"
                                label="Entity"
                                value={agent.entity}
                                icon={entityIcon}
                                onClick={selectEntity}
                                buttonCaption="Select..."
                                validate={validateAgent("entity")}
                            />
                            {isEntityFound ||
                                <ErrorBanner>
                                    {`Entity with name ${agent.entity} does not exist (anymore). Please select a valid entity.`}
                                </ErrorBanner>}
                        </FormDivider>
                    </ContentColumn>
                </PageContent>}
            </PageContainer>
        </AppThemeProvider>
    );
};

export const component: IComponent = createDocumentEditorComponent(App);